{
  "domains": [
    {
      "domain": "BrowserUse",
      "description": "Custom domain for BrowserUse specific automation events.",
      "types": [],
      "commands": [],
      "events": [
        {
          "name": "captchaSolverStarted",
          "description": "Captcha solving started.",
          "parameters": [
            {
              "name": "targetId",
              "$ref": "Target.TargetID"
            },
            {
              "name": "vendor",
              "type": "string"
            },
            {
              "name": "url",
              "type": "string"
            },
            {
              "name": "startedAt",
              "type": "integer",
              "description": "Unix millis"
            },
            {
              "name": "eventTimeout",
              "type": "number",
              "optional": true
            }
          ]
        },
        {
          "name": "captchaSolverFinished",
          "description": "Captcha solving finished.",
          "parameters": [
            {
              "name": "targetId",
              "$ref": "Target.TargetID"
            },
            {
              "name": "vendor",
              "type": "string"
            },
            {
              "name": "url",
              "type": "string"
            },
            {
              "name": "durationMs",
              "type": "integer"
            },
            {
              "name": "finishedAt",
              "type": "integer",
              "description": "Unix millis"
            },
            {
              "name": "success",
              "type": "boolean",
              "description": "Whether the captcha was solved successfully"
            },
            {
              "name": "eventTimeout",
              "type": "number",
              "optional": true
            }
          ]
        },
        {
          "name": "activeTargetChanged",
          "description": "Fired when a target is activated via Target.activateTarget.",
          "parameters": [
            {
              "name": "targetId",
              "$ref": "Target.TargetID"
            },
            {
              "name": "eventTimeout",
              "type": "number",
              "optional": true
            }
          ]
        }
      ]
    }
  ]
}
